window.AUTH=window.AUTH||{};window.AUTH["19-5410"]={"d":"19-5410","id":"2020/19-5410","n":"Borden v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Charles Borden, Jr.","date":"2020-04-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-5410/142425/20200427091520815_Borden%20brief%20for%20petitioner.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent United States of America","date":"2020-06-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-5410/145158/20200608155359565_19-5410bsUnitedStates.pdf","side":"res","n":103},{"k":"reply","label":"Reply of petitioner Charles Borden, Jr.","date":"2020-07-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-5410/147185/20200708101447129_2020.07.08%20Borden%20reply%20brief%20for%20petitioner%20FINAL.pdf","side":"pet","n":30}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r44_3eah.pdf","tr":true,"items":[{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"by":{"0":"passim","1":"27, 28, 30, 39, 44","2":"passim"},"q":[{"src":"brief","b":0,"text":"focuses upon the special danger created when a particular type of offender—a violent criminal or drug trafficker—possesses a gun.","cite":"553 U.S. 137, 146"},{"src":"brief","b":0,"text":"associated with a likelihood of future violent, aggressive, and purposeful ‘armed career criminal’ behavior.","cite":"553 U.S. at 148"},{"src":"brief","b":1,"text":"likelihood that the offender is the kind of person who might deliberately point [a] gun and pull the trigger,","cite":"553 U.S. at 146"},{"src":"brief","b":2,"text":"reveal a degree of callousness toward risk","cite":"553 U.S. at 146"},{"src":"brief","b":2,"text":"the offender is the kind of person who might deliberately point the gun and pull the trigger.","cite":"553 U.S. at 146"}]},{"t":"case","label":"Bennett v. United States","cite":"868 F.3d 1","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/868/1/","by":{"0":"29, 44"},"q":[{"src":"brief","b":0,"text":"must be construed to include reckless offenses when a version of that same language was for so long and so uniformly construed to exclude them.","cite":"868 F.3d at 8"}]},{"t":"case","label":"Bowsher v. Merck & Co.","cite":"460 U.S. 824","y":1983,"id":"1982/81-1273","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"words of limitation designed to restrict","cite":"460 U.S. 824, 827 n.3"}]},{"t":"case","label":"Collins v. State, Crim. No. 09-04-407","cite":"2005 WL 3074154","y":2005,"court":"Tex. Ct. App. June 8","by":{"0":"39","1":"40"}},{"t":"case","label":"Craver v. State, Crim. No. 02-14-76","cite":"2015 WL 3918057","y":2015,"court":"Tex. Ct. App. June 25","by":{"0":"41","1":"44"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"by":{"0":"7"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"by":{"0":"19"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"duty to give effect, if possible, to every clause and word of a statute.","cite":"533 U.S. 167, 174"}]},{"t":"case","label":"Elonis v. United States","cite":"135 S. Ct. 2001","y":2015,"id":"2014/13-983","sc":1,"by":{"0":"25","1":"15, 27"}},{"t":"case","label":"Fernandez-Ruiz v. Gonzales","cite":"466 F.3d 1121","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/466/1121/","by":{"0":"9, 28, 29"}},{"t":"case","label":"Garcia v. Gonzales","cite":"455 F.3d 465","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/455/465/","by":{"0":"9, 28"}},{"t":"case","label":"Global-Tech Appliances, Inc. v. SEB S.A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"by":{"0":"26"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"by":{"0":"26"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"by":{"0":"7, 23, 34","1":"31, 32, 33","2":"10"},"q":[{"src":"brief","b":0,"text":"connotes a substantial degree of force.","cite":"559 U.S. at 140"},{"src":"brief","b":0,"text":"calls to mind a tradition of crimes that involve the possibility of more closely related, active violence.","cite":"559 U.S. at 141"},{"src":"brief","b":1,"text":"in the context of a statutory definition of ‘violent felony,’","cite":"559 U.S. at 140"},{"src":"brief","b":2,"text":"a statutory definition of ‘violent felony’","cite":"559 U.S. 133, 140"},{"src":"brief","b":2,"text":"calls to mind a tradition of crimes that involve the possibility of more closely related, active violence.","cite":"559 U.S. at 141"}]},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"6, 26"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"by":{"0":"passim","1":"13, 39","2":"passim"},"q":[{"src":"brief","b":0,"text":"against the person * * * of another.","cite":"543 U.S. 1, 9"},{"src":"brief","b":0,"text":"in its context and in light of the terms surrounding it.","cite":"543 U.S. at 8"},{"src":"brief","b":1,"text":"require only proof that the person acted negligently in operating the vehicle.","cite":"543 U.S. at 7"},{"src":"brief","b":2,"text":"against the person * * * of another.","cite":"543 U.S. at 9"},{"src":"argument","who":"Mr. Shanmugam","text":"Until recently, our interpretation was the uniform interpretation of the courts of appeals, which relied on the text of the force clause and this Court's decision in Leocal construing it."},{"src":"argument","who":"Chief Justice Roberts","text":"You -- you rely heavily on Leocal and its statement, just to quote, that \"it's not natural to say that a person actively employs physical force against another person by accident.\" I'm not sure I understand that."},{"src":"argument","who":"Mr. Shanmugam","text":"But we're really relying on a separate aspect of Leocal's reasoning, that is, that the \"against\" phrase is the critical and key phrase that limits the use of physical force and that defines the necessary degree of intent."}]},{"t":"case","label":"Mayhew v. State","cite":"271 S.W.3d 294","y":2008,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W.3d/271/294/","by":{"0":"41"}},{"t":"case","label":"Oyebanji v. Gonzales","cite":"418 F.3d 260","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/418/260/","by":{"0":"24, 39","2":"10, 19"},"q":[{"src":"brief","b":0,"text":"[t]he quintessential violent crimes—murder, assault, battery, rape, etc.—involve the intentional use of actual or threatened force against another’s person.","cite":"418 F.3d 260, 264"},{"src":"brief","b":0,"text":"interpret that separate listing as suggesting that injury-causing reckless driving offenses in particular are excluded from the category of crimes of violence.","cite":"418 F.3d at 264"},{"src":"brief","b":2,"text":"ordinary meaning of the term ‘violent’ crime.","cite":"418 F.3d 260, 264"},{"src":"argument","who":"Mr. Shanmugam","text":"I think our principal submission, Justice Alito, is simply the -- the point that you made on the Third Circuit in the Oyebanji case, and that is that a reckless offense, an offense involving ordinary recklessness, although involving a substantial degree of moral culpability, does not fall within the ordinary meaning of violent crime, much less the ordinary meaning of violent felony."}]},{"t":"case","label":"Popal v. Gonzales","cite":"416 F.3d 249","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/416/249/","by":{"0":"9, 28"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"by":{"0":"5","1":"8, 33"},"q":[{"src":"brief","b":1,"text":"not lightly conclude that Congress enacted a self-defeating statute,","cite":"139 S. Ct. 1872, 1879"},{"src":"brief","b":1,"text":"should not lightly conclude that Congress enacted a self-defeating statute.","cite":"139 S. Ct. 1872, 1879"},{"src":"argument","who":"Mr. Feigin","text":"And I guess the second and related point I would make about that is, to the extent that my friend's position depends on these kind of isolated examples of seemingly innocuous conduct that might in theory be covered by one of these statutes, this Court in -- in Quarles may recall that one of the major arguments made there was that there were seemingly innocuous ways to commit certain forms of burglary."},{"src":"argument","who":"Mr. Feigin","text":"And I'd also emphasize something this Court said at the end of Quarles, which is that at the end of the Quarles opinion, it makes clear that what's really required under the Taylor categorical approach is some kind of rough correspondence and that we don't look at these very minute curlicues of -- of particular state laws."}]},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"the words describe an element of a criminal offense.","cite":"510 U.S. at 141"}]},{"t":"case","label":"Seaton v. State","cite":"385 S.W.3d 85","y":2012,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W.3d/385/85/","by":{"0":"40","1":"44"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"by":{"0":"40","1":"43"}},{"t":"case","label":"State v. Cope, Misc. No. 2014-775","cite":"2015 WL 4880347","y":2015,"court":"Tenn. Crim. App. Aug. 14","by":{"0":"38","1":"40"}},{"t":"case","label":"State v. Gimino","cite":"2015 WL 13134204","y":2015,"court":"Wis. Ct. App. Apr. 15","by":{"0":"40"}},{"t":"case","label":"State v. Norris","cite":"874 S.W.2d 590","y":1993,"court":"Tenn. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/874/590/","by":{"0":"38","1":"40"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"by":{"0":"41","1":"passim","2":"14"},"q":[{"src":"brief","b":1,"text":"mirrored the elements of the common-law crime of robbery.","cite":"139 S. Ct. 544, 550"},{"src":"brief","b":1,"text":"capable of causing physical pain or injury to another person,","cite":"139 S. Ct. 544, 553"},{"src":"argument","who":"Mr. Feigin","text":"And if you look at the set of offenses that they would cut out, which are felony assault by injury, second degree murder, and common law robbery, which the Court described in Stokeling as the paradigmatic elements clause offense, I think it's quite clear that our reading is much better than theirs."},{"src":"argument","who":"Mr. Feigin","text":"I think one example is the Court's own recent decision in Stokeling. Stokeling recognized that a typical robbery offense involving a struggle for an item satisfies the elements clause."}]},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"by":{"0":"8, 26","2":"11"},"q":[{"src":"brief","b":2,"text":"Begay involved a crime akin to strict-liability, negligence, and recklessness crimes.","cite":"564 U.S. 1, 13"},{"src":"argument","who":"Mr. Shanmugam","text":"In Begay and then in Sykes, this Court had a very vigorous back and forth on whether the residual clause extended to reckless offenses. And I think, by the end of Sykes, the Court had effectively restricted the residual clause to intentional offenses."}]},{"t":"case","label":"Tam Ha Huynh v. State, Crim. No. 03-17-645","cite":"2018 WL 4100849","y":2018,"court":"Tex. Ct. App. Aug. 29","by":{"0":"38","1":"40"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"0":"24","1":"2, 3, 5, 28, 29","2":"13, 14"},"q":[{"src":"brief","b":1,"text":"supplement the States’ law enforcement efforts against ‘career’ criminals.","cite":"495 U.S. 575, 581"},{"src":"brief","b":1,"text":"expand[] the predicate offenses triggering the sentence enhancement from ‘robbery or burglary’ to ‘a violent felony or a serious drug offense.’","cite":"495 U.S. at 582"}]},{"t":"case","label":"United States v. Bailey","cite":"444 U.S. 394","y":1980,"id":"1979/78-990","sc":1,"by":{"0":"4","1":"26"}},{"t":"case","label":"United States v. Boose","cite":"739 F.3d 1185","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/1185/","by":{"0":"9, 28, 29"}},{"t":"case","label":"United States v. Burris","cite":"920 F.3d 942","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/920/942/","by":{"0":"36","1":"11, 34"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"0":"passim","1":"10, 31, 45, 46","2":"8, 9"},"q":[{"src":"brief","b":0,"text":"hesitated * * * to apply the [ACCA] to crimes which, though dangerous, are not typically committed by those whom one normally labels ‘armed career criminals.’","cite":"572 U.S. 157, 167"},{"src":"brief","b":0,"text":"may not constitute ‘violence’ in the generic sense.","cite":"572 U.S. at 165"},{"src":"brief","b":1,"text":"there remains a grievous ambiguity or uncertainty in the statute, such that the Court must simply guess as to what Congress intended.","cite":"572 U.S. 157, 173"},{"src":"brief","b":1,"text":"But ‘the rule of lenity only applies if, after considering text, structure, history, and purpose, there remains a grievous ambiguity or uncertainty in the statute, such that the Court must simply guess as to what Congress intended.’","cite":"572 U.S. at 172"},{"src":"argument","who":"Mr. Shanmugam","text":"In Castleman, this Court already held that the statute at issue here and the statute at issue in Voisine should be construed differently in light of their different contexts."}]},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"ambiguities about the breadth of a criminal statute should be resolved in the defendant’s favor.","cite":"139 S. Ct. 2319, 2333"}]},{"t":"case","label":"United States v. Doe","cite":"960 F.2d 221","y":1992,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/960/221/","by":{"0":"23, 34","2":"10"},"q":[{"src":"brief","b":0,"text":"violent felony * * * calls to mind a tradition of crimes that involve the possibility of more closely related, active violence.","cite":"960 F.2d 221, 225"}]},{"t":"case","label":"United States v. Fogg","cite":"836 F.3d 951","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/836/951/","by":{"0":"36","1":"11"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"43"}},{"t":"case","label":"United States v. Haight","cite":"892 F.3d 1271","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1271/","by":{"0":"36, 39","1":"11, 14"}},{"t":"case","label":"United States v. Harper","cite":"875 F.3d 329","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/329/","by":{"0":"12, 13","2":"6"},"q":[{"src":"brief","b":2,"text":"one of the more familiar in criminal law.","cite":"875 F.3d 329, 333"}]},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"by":{"0":"34"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"by":{"0":"43, 44","2":"21"},"q":[{"src":"brief","b":0,"text":"promot[ing] fair notice to those subject to the criminal laws, * * * minimiz[ing] the risk of selective or arbitrary enforcement, and * * * maintain[ing] the proper balance between Congress, prosecutors, and courts.","cite":"487 U.S. 931, 952"},{"src":"brief","b":2,"text":"uncertainty concerning the ambit of criminal statutes should be resolved in favor of lenity.","cite":"487 U.S. 931, 952"}]},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 529","y":1997,"id":"1996/95-1717","sc":1,"by":{"0":"42"}},{"t":"case","label":"United States v. McMurray","cite":"653 F.3d 367","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/653/367/","by":{"0":"9, 11, 28"}},{"t":"case","label":"United States v. Middleton","cite":"883 F.3d 485","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/485/","by":{"0":"37, 42","2":"17"}},{"t":"case","label":"United States v. Moreno","cite":"821 F.3d 223","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/821/223/","by":{"0":"9, 28"}},{"t":"case","label":"United States v. Orona","cite":"923 F.3d 1197","y":2019,"court":"Nov. 18","url":"https://www.courtlistener.com/c/F.3d/923/1197/","by":{"0":"37","1":"37"}},{"t":"case","label":"United States v. Palomino Garcia","cite":"606 F.3d 1317","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/606/1317/","by":{"0":"9, 29"}},{"t":"case","label":"United States v. Pam","cite":"867 F.3d 1191","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1191/","by":{"0":"36","1":"11"}},{"t":"case","label":"United States v. Portela","cite":"469 F.3d 496","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/469/496/","by":{"0":"11"}},{"t":"case","label":"United States v. Resendiz-Ponce","cite":"549 U.S. 102","y":2007,"id":"2006/05-998","sc":1,"by":{"0":"25","1":"27"}},{"t":"case","label":"United States v. Rutherford","cite":"54 F.3d 370","y":1995,"url":"https://www.courtlistener.com/c/F.3d/54/370/","by":{"0":"9, 28, 29"}},{"t":"case","label":"United States v. United States Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"by":{"0":"5"}},{"t":"case","label":"United States v. Vargas-Duran","cite":"356 F.3d 598","y":2004,"url":"https://www.courtlistener.com/c/F.3d/356/598/","by":{"0":"9, 28"}},{"t":"case","label":"United States v. Verwiebe","cite":"874 F.3d 258","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/258/","by":{"0":"12, 13, 36","1":"6, 7, 14, 25"},"q":[{"src":"brief","b":1,"text":"a mental state of recklessness suffices for conviction.","cite":"874 F.3d at 261"},{"src":"opinion","who":"Justice Thomas, concurring in the judgment","text":"Voisine's key insight is that the word `use' refers to `the act of employing something' and does not require a purposeful or knowing state of mind. That insight does not change if a statute says that the `use of physical force' must be `against' a person, property, or for that matter anything else. . . . Sometimes the simplest explanation is the best explanation.","cite":"874 F. 3d 258, 262–263"},{"src":"argument","who":"Justice Kavanaugh","text":"Judge Sutton in Verwiebe -- he's a very wise judge, as you know -- said sometimes the simplest explanation is the best explanation. And it seems like, if you're trying to make sense of Leocal and Voisine together, the simplest and I think potentially the best explanation -- I want to get your reaction -- is negligent conduct is not use of force and reckless conduct is use of force for purposes of these statutes because, I think to pick up on what Justice Thomas said, it would be a bit wild to say reckless crimes are covered by \"use of force\" statutes but not by \"use of force against another\" statutes."}]},{"t":"case","label":"United States v. Windley","cite":"864 F.3d 36","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/864/36/","by":{"0":"37, 44"}},{"t":"case","label":"United States v. Zuniga-Soto","cite":"527 F.3d 1110","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/527/1110/","by":{"0":"9, 29"}},{"t":"case","label":"Voisine v. United States","cite":"136 S. Ct. 2272","y":2016,"id":"2015/14-10154","sc":1,"by":{"0":"passim","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"bar those domestic abusers convicted of garden-variety assault or battery misdemeanors * * * from owning guns.","cite":"136 S. Ct. at 2280"},{"src":"brief","b":1,"text":"Voisine’s key insight is that the word ‘use’ refers to ‘the act of employing something’ and does not require a purposeful or knowing state of mind.","cite":"136 S. Ct. at 2278"},{"src":"brief","b":1,"text":"suggests a different conclusion—i.e., that ‘use’ marks a dividing line between reckless and knowing conduct.","cite":"136 S. Ct. at 2279"},{"src":"brief","b":2,"text":"to ‘close a dangerous loophole’ in the gun control laws.","cite":"136 S. Ct. at 2276"},{"src":"argument","who":"Mr. Shanmugam","text":"But, in the wake of this Court's decision four years ago in Voisine, some courts of appeals, including the court below, reversed course and adopted a contrary interpretation."},{"src":"argument","who":"Mr. Shanmugam","text":"And that's really how to reconcile Leocal with Voisine. In Voisine, the Court was interpreting a statute that lacked that limiting language, and the Court appropriately relied on the aspect of Leocal's reasoning to which you point in holding that the unlimited language reaches more broadly."},{"src":"argument","who":"Justice Thomas","text":"Counsel, I'd like you to go back to your reliance on the \"against\" phrase and your efforts to distance this case from Voisine. I thought that in Voisine, that the statute there covered the use of force by a person with whom the victim shares a child in common, by a person who is cohabit -- cohabiting with or has cohabited with the victim as a spouse."}]},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","id":"2014/13-7451","sc":1,"by":{"0":"43"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(1)","(e)(2)(B)","(e)(2)(B)(i)","(e)(2)(B)(ii)","(a)(2)","(e)(2)","(c)","(c)(1)(A)","(c)(3)(A)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 6, 26, 28, passim, 6, 27, 5, 24","1":"2, 30, 2, 19, 2, 19, 2, 19, 2, 19, 9, 35, 36, 37, 37, 37","2":"passim, 5, 13, 11, 20"},"q":[{"src":"brief","b":0,"text":"use * * * of physical force against the person of another.","cite":"18 U.S.C. 924(e)(2)(B)(i)"},{"src":"brief","b":0,"text":"has as an element the use, attempted use, or threatened use of physical force against the person of another.","cite":"18 U.S.C. 924(e)(2)(B)(i)"},{"src":"brief","b":1,"text":"violent felony or a serious drug offense, or both, committed on occasions different from one another.","cite":"18 U.S.C. 924(e)(1)"},{"src":"brief","b":1,"text":"as an element the use, attempted use, or threatened use of physical force against the person of another.","cite":"18 U.S.C. 924(e)(2)(B)(i)"},{"src":"brief","b":2,"text":"the use * * * of physical force.","cite":"18 U.S.C. 924(e)(2)(B)(i)"},{"src":"brief","b":2,"text":"presents a serious potential risk of physical injury to another.","cite":"18 U.S.C. 924(e)(2)(B)(ii)"},{"src":"opinion","who":"Justice Thomas, concurring in the judgment","text":"three previous convictions . . . for a violent Thomas, J., concurring in judgment felony or a serious drug offense.","cite":"18 U. S. C. § 924(e)(1)"},{"src":"opinion","who":"Justice Thomas, concurring in the judgment","text":"has as an element the use, attempted use, or threatened use of physical force against 3 Voting to affrm petitioner's sentence here would lead to a 5 to 4 judgment that petitioner's sentence is correct even though fve Justices conclude that Tennessee reckless aggravated assault does not satisfy the elements clause. That kind of fractured reasoning would be diffcult for lower courts to apply. Kavanaugh, J., dissenting the person of another.","cite":"18 U. S. C. § 924(e)(2)(B)(i)"}]},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"28","1":"3"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(h)","(a)(43)(F)","(h)(3)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39, 39","1":"35, 35, 36, 42, 42","2":"19, 19"},"q":[{"src":"brief","b":0,"text":"any crime of reckless driving * * * if such crime involves personal injury to another.","cite":"8 U.S.C. 1101(h)"},{"src":"brief","b":1,"text":"crime involves personal injury to another,","cite":"8 U.S.C. 1101(h)"},{"src":"brief","b":2,"text":"any crime of reckless driving or of driving while intoxicated or under the influence of alcohol * * * if such crime involves personal injury to another.","cite":"8 U.S.C. 1101(h)"}]},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(2)(E)"],"by":{"0":"39"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(a)"],"stext":{"head":"§16. Crime of violence defined","paras":[[0,"The term \"crime of violence\" means—"],[1,"(a) an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(b) any other offense that is a felony and that, by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/16?type=usc&year=mostrecent&link-type=html"},"by":{"0":"10, 39, 7, 21, 34","1":"13, 25, 35, 36, 13, 25, 35, 36","2":"19, 20, passim"},"q":[{"src":"brief","b":1,"text":"an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another.","cite":"18 U.S.C. 16(a)"},{"src":"brief","b":2,"text":"an offense that has as an element the use * * * of physical force against the person or property of another.","cite":"18 U.S.C. 16(a)"},{"src":"argument","who":"Justice Sotomayor","text":"I'm quoting from your Voisine brief: \"While both provisions contain the phrase use of physical force, the domestic violence provision, and ACCA, the misdemeanor crime of violence definition omits the remainder of the Leocal's provision Section 16 definition, which qualifies that the force is against the person or property of another.\" You said the \"against\" phrase was crucial to Leocal's holding, which required a higher mens rea."}]},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(33)(A)","(a)(33)(A)(ii)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16, 30, 9, 36","1":"9, 35, 36, 37, 9, 35, 36, 37"},"q":[{"src":"brief","b":0,"text":"the use or attempted use of physical force * * * committed by [certain family members] of the victim.","cite":"18 U.S.C. 921(a)(33)(A)"},{"src":"brief","b":1,"text":"the use or attempted use of physical force.","cite":"18 U.S.C. 921(a)(33)(A)(ii)"}]},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)","(g)(9)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 2, passim","1":"9, 35, 36, 37, 9, 35, 36, 37, 9, 35, 36, 37","2":"9, 7, 8, 9, 20"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(e)"],"by":{"0":"12","1":"6"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"by":{"1":"45"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"1":"43"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"by":{"1":"9, 26"},"q":[{"src":"brief","b":1,"text":"read[] words or elements into a statute that do not appear on its face.","cite":"522 U.S. 23, 29"}]},{"t":"case","label":"Braden v. United States","cite":"817 F.3d 926","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/817/926/","by":{"1":"5"}},{"t":"case","label":"Commonwealth v. Burno","cite":"487 N.E.2d 1366","y":1986,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/487/1366/","by":{"1":"20"}},{"t":"case","label":"Cooper v. State","cite":"265 A.2d 569","y":1970,"court":"Md. Ct. Spec. App.","url":"https://www.courtlistener.com/c/A.2d/265/569/","by":{"1":"18"}},{"t":"case","label":"Cuevas v. State","cite":"576 S.W.3d 398","y":2019,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/576/398/","by":{"1":"44"}},{"t":"case","label":"Davis v. United States","cite":"900 F.3d 733","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/900/733/","by":{"1":"11"}},{"t":"case","label":"DuPree v. State","cite":"310 So. 2d 396","y":1975,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/310/396/","by":{"1":"20"}},{"t":"case","label":"Farm Bureau Mut. Auto. Ins. Co. v. Hammer","cite":"177 F.2d 793","y":1949,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/177/793/","by":{"1":"38"}},{"t":"case","label":"Farmer v. Brennan","cite":"511 U.S. 825","y":1994,"id":"1993/92-7247","sc":1,"by":{"1":"12, 16"}},{"t":"case","label":"Garrison v. Louisiana","cite":"379 U.S. 64","y":1964,"id":"1964/4","sc":1,"by":{"1":"16"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"by":{"1":"21"}},{"t":"case","label":"Hall v. State","cite":"158 S.W.3d 470","y":2005,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/158/470/","by":{"1":"44"}},{"t":"case","label":"Harris v. United States","cite":"8 App. D.C. 20","y":1896,"url":"https://www.courtlistener.com/c/App.%20D.C./8/20/","by":{"1":"21"}},{"t":"case","label":"Henderson v. State","cite":"70 S.E.2d 713","y":1952,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/70/713/","by":{"1":"18"}},{"t":"case","label":"Kirk v. United States","cite":"481 Fed. Appx. 249","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./481/249/","by":{"1":"41, 41"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"by":{"1":"5, 43"},"q":[{"src":"brief","b":1,"text":"a sentencing court looks to a limited class of documents * * * to determine what crime, with what elements, a defendant was convicted of.","cite":"136 S. Ct. 2243, 2249"}]},{"t":"case","label":"Moore v. State","cite":"18 Ala. 532","y":1851,"url":"https://www.courtlistener.com/c/Ala./18/532/","by":{"1":"21"}},{"t":"case","label":"Nestlerode v. United States","cite":"122 F.2d 56","y":1941,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/122/56/","by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"while driving on the wrong side of the street,","cite":"122 F.2d at 57, 59"}]},{"t":"case","label":"New York Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"by":{"1":"16"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"by":{"1":"43"}},{"t":"case","label":"Parker v. United States","cite":"359 F.2d 1009","y":1966,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/359/1009/","by":{"1":"20"}},{"t":"case","label":"People v. Potter","cite":"5 Mich. 1","y":1858,"url":"https://www.courtlistener.com/c/Mich./5/1/","by":{"1":"21"}},{"t":"case","label":"Shiflet v. State","cite":"392 S.W.2d 676","y":1965,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W.2d/392/676/","by":{"1":"38"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"by":{"1":"45"}},{"t":"case","label":"State v. Day","cite":"2017 WL 3206605","y":2017,"court":"Tenn. Crim. App. July 27","by":{"1":"42"}},{"t":"case","label":"State v. Farris","cite":"542 P.2d 725","y":1975,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/542/725/","by":{"1":"20"}},{"t":"case","label":"State v. Jarnagin","cite":"1997 WL 624862","y":1997,"court":"Tenn. Crim. App. Oct. 9","by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"slamm[ed] his fist into the face of a man whom he did not know and who had done nothing more threatening than walk behind him in a parking lot,","cite":"1997 WL 624862"}]},{"t":"case","label":"State v. McAmis","cite":"2010 WL 2244124","y":2010,"court":"Tenn. Crim. App. June 4","by":{"1":"42"}},{"t":"case","label":"State v. Nolan","cite":"2015 WL 5838739","y":2015,"court":"Tenn. Crim. App. Oct. 7","by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"sw[u]ng[] a hot, metal pipe at [a woman], and [a different victim] was hit while attempting to break up the altercation,","cite":"2015 WL 5838739"}]},{"t":"case","label":"State v. Patterson","cite":"88 P.2d 493","y":1939,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/88/493/","by":{"1":"20"}},{"t":"case","label":"State v. Royball","cite":"710 P.2d 168","y":1985,"court":"Utah","url":"https://www.courtlistener.com/c/P.2d/710/168/","by":{"1":"20"}},{"t":"case","label":"State v. Trott","cite":"130 S.E. 627","y":1925,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./130/627/","by":{"1":"38"}},{"t":"case","label":"State v. Turner","cite":"953 S.W.2d 213","y":1996,"court":"Tenn. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/953/213/","by":{"1":"39"}},{"t":"case","label":"Tarver v. State","cite":"16 S.W. 1941","y":1891,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W./16/1941/","by":{"1":"21"}},{"t":"case","label":"Thornton v. United States","cite":"2018 WL 1088028","y":2018,"court":"M.D. Pa. Feb. 28","by":{"1":"41"}},{"t":"case","label":"Tift v. State","cite":"88 S.E. 41","y":1916,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E./88/41/","by":{"1":"38"}},{"t":"case","label":"Tison v. Arizona","cite":"481 U.S. 137","y":1987,"id":"1986/84-6075","sc":1,"by":{"1":"16"}},{"t":"case","label":"United States v. Begay","cite":"934 F.3d 1033","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/1033/","by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"may be committed recklessly— with a depraved heart mental state—and need not be committed willfully or intentionally.","cite":"934 F.3d 1033, 1039-1040"}]},{"t":"case","label":"United States v. Bettcher","cite":"911 F.3d 1040","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/911/1040/","by":{"1":"46"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"by":{"1":"43"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"And it was really for that reason that this Court, in a case called United States versus Hayes, in an opinion written by Justice Ginsburg, concluded that the relationship with the victim is not even an element under Section 922(g)(9)."}]},{"t":"case","label":"United States v. Herrick","cite":"545 F.3d 53","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/545/53/","by":{"1":"41"}},{"t":"case","label":"United States v. Penny","cite":"220 Fed. Appx. 449","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./220/449/","by":{"1":"41"}},{"t":"case","label":"Virginia v. Black","cite":"538 U.S. 343","y":2003,"id":"2002/01-1107","sc":1,"by":{"1":"33"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2185","by":{"1":"2, 17, 19, 35"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(E)(i)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"by":{"1":"36","2":"20"}},{"t":"usc","label":"18 U.S.C. § 113","url":"https://www.law.cornell.edu/uscode/text/18/113","subs":["(a)(4)","(a)(5)","(a)(6)","(d)(1982)","(e)(1982)","(a)(3)"],"by":{"1":"35, 35, 36, 36, 35, 35, 35, 35","2":"19"}},{"t":"usc","label":"18 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/18/1111","subs":["(a)"],"by":{"1":"37"}},{"t":"case","label":"Schad v. Arizona","cite":"501 U.S. 624","y":1991,"id":"1990/90-5551","sc":1,"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"modified the common law by legislation classifying murder by degrees.","cite":"501 U.S. 624, 640"}]},{"t":"case","label":"(I) Cases—continued: United States v. Schneider","cite":"905 F.3d 1088","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/905/1088/","by":{"2":"14, 18"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"by":{"2":"17"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"by":{"2":"14"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"2":"20"}}]};